#include <cstdio>
#include <queue>
#include <cstring>
#include <climits>
#include <vector>
using namespace std;

typedef pair<int, int> pii; // Pair to store (distance, node)
priority_queue<pii, vector<pii>, greater<pii>> Q; // Min-heap for priority queue
int island, query, kind, start, goal, price;
int connect[101][101];
int dis[101];

void initializeGraph() {
    for (int i = 0; i < 101; i++) {
        fill(connect[i], connect[i] + 101, INT_MAX);
    }
}

void calculateShortestPath() {
    fill(dis, dis + 101, INT_MAX);
    dis[start] = 0;
    Q.push({0, start}); // Push the start node with distance 0

    while (!Q.empty()) {
        int current = Q.top().second;
        Q.pop();

        for (int i = 1; i <= island; i++) {
            if (connect[current][i] != INT_MAX && dis[i] > dis[current] + connect[current][i]) {
                dis[i] = dis[current] + connect[current][i];
                Q.push({dis[i], i}); // Push updated distance and node
            }
        }
    }
}

int main() {
    scanf("%d %d", &island, &query);
    while (island != 0) {
        initializeGraph();
        for (int i = 0; i < query; i++) {
            scanf("%d", &kind);
            if (kind == 1) {
                scanf("%d %d %d", &start, &goal, &price);
                connect[start][goal] = min(connect[start][goal], price);
                connect[goal][start] = connect[start][goal]; // Avoiding redundant checks
            } else {
                scanf("%d %d", &start, &goal);
                calculateShortestPath();
                printf("%d\n", dis[goal] == INT_MAX ? -1 : dis[goal]);
            }
        }
        scanf("%d %d", &island, &query);
    }
    return 0;
}

