    while (!Q.empty()) {
        int current = Q.front();
        Q.pop();
        for (const auto& edge : connections[current]) {
            int neighbor = edge.first;
            int weight = edge.second;
            if (dis[neighbor] > dis[current] + weight) {
                dis[neighbor] = dis[current] + weight;
                Q.push(neighbor);
            }
        }
    }
